/**
 * The text that can say why a Change exists: PR descriptions, linked issues,
 * commit messages, and the comments and test names that the diff adds.
 * Pure text rules, no LLM. Each function keeps what an author wrote about the
 * work and drops what tools, templates and bots add.
 */
import type { Hunk } from "../model/change.js";

/** Text that ends the author's part of a PR body: tool footers. */
const FOOTERS = [
  "<!-- CURSOR_AGENT_PR_BODY_END -->",
  "<!-- codesmith:footer -->",
  "<!-- Generated by",
  "🤖 Generated with",
];

/** Lines that tools add to a body or a commit message. */
const BOILERPLATE_LINE =
  /^\s*(_?Requested by\b|Co-Authored-By:|Signed-off-by:|Claude-Session:|Change-Id:|https:\/\/claude\.ai\/code\/session_\S*$)/i;

/** Sections that hold proof, not reasons. The Verification view reads them. */
const PROOF_HEADING =
  /verif|screenshot|screen ?shot|recording|video|demo|before.+after|\bqa\b|proof|evidence|test plan|testing|how (i|we) (checked|tested)|checklist/i;

/** A template's checkbox line. */
const CHECKBOX = /^\s*[-*+]\s+\[[ xX]\]/;
/** A bare uploaded asset on its own line, which GitHub shows as a video. */
const ASSET_LINE = /^\s*https:\/\/github\.com\/user-attachments\/assets\/[\w-]+\s*$/;

/**
 * A PR or issue body as the author's own words: no footers, comments,
 * pictures, checklists, proof sections or empty template headings.
 */
export function cleanDescription(body: string | null | undefined): string {
  if (!body) return "";
  let text = body.replace(/\r\n/g, "\n");
  for (const footer of FOOTERS) {
    const at = text.indexOf(footer);
    if (at >= 0) text = text.slice(0, at);
  }
  text = text
    .replace(/<!--[\s\S]*?-->/g, "")
    .replace(/<picture>[\s\S]*?<\/picture>/gi, "")
    .replace(/<video[\s\S]*?<\/video>/gi, "")
    .replace(/<img\b[^>]*>/gi, "")
    .replace(/!\[[^\]]*\]\([^)]*\)/g, "");

  const out: string[] = [];
  // The heading path of the current section, and the lines kept since its heading.
  const headings: { level: number; title: string }[] = [];
  let pending: string | null = null;
  let skip = false;
  for (const line of text.split("\n")) {
    const heading = /^(#{1,6})\s+(.*?)\s*#*\s*$/.exec(line);
    if (heading) {
      const level = (heading[1] as string).length;
      while (
        headings.length > 0 &&
        (headings[headings.length - 1] as { level: number }).level >= level
      )
        headings.pop();
      headings.push({ level, title: heading[2] as string });
      skip = headings.some((h) => PROOF_HEADING.test(h.title));
      // A heading is kept only once a line under it is.
      pending = skip ? null : line.trim();
      continue;
    }
    if (skip) continue;
    if (CHECKBOX.test(line) || ASSET_LINE.test(line) || BOILERPLATE_LINE.test(line)) continue;
    if (line.trim() === "") {
      if (out.length > 0 && out[out.length - 1] !== "") out.push("");
      continue;
    }
    if (pending !== null) {
      if (out.length > 0 && out[out.length - 1] !== "") out.push("");
      out.push(pending);
      pending = null;
    }
    out.push(line.trimEnd());
  }
  return out.join("\n").trim();
}

/** Subjects that say nothing about why. */
const TRIVIAL_SUBJECT =
  /^(merge\b|fixup!|squash!|amend!|wip\b|revert "?wip|lint\b|format\b|typo\b|fix (lint|tests?|types?|ci|build)\b|address (review|comments|feedback)\b|pr feedback\b|review feedback\b|update\s*$)/i;

/**
 * A commit message with its trailers taken off. Null for merges, fixups, WIP
 * and other messages too short to say anything.
 */
export function cleanCommitMessage(message: string): string | null {
  const lines = message
    .replace(/\r\n/g, "\n")
    .split("\n")
    .filter((line) => !BOILERPLATE_LINE.test(line));
  const subject = (lines[0] ?? "").trim();
  const body = lines.slice(1).join("\n").trim();
  if (!subject || TRIVIAL_SUBJECT.test(subject)) return null;
  if (!body && subject.length < 15) return null;
  return body ? `${subject}\n\n${body}` : subject;
}

/** Comment lines that only steer a tool. */
const TOOL_COMMENT =
  /eslint|biome-ignore|noqa|type:\s*ignore|@ts-|prettier-ignore|istanbul|pragma|pylint|nolint|rubocop|SPDX|copyright|^#!|^\s*#\s*(include|define|if|endif|region|endregion)\b/i;

/** The first marker that opens a comment line, in the languages Strata reads. */
const COMMENT_START = /^\s*(\/\/+|#+|\/\*+|\*+\/?|--|<!--|"""|''')\s?(.*)$/;
const TEST_NAME =
  /\b(?:it|test|describe|context|scenario)\s*(?:\.\w+)?\s*\(\s*(["'`])(.+?)\1|\bdef\s+(test_\w+)|\bfunc\s+(Test\w+)/;

const LINES_PER_HUNK = 12;
const LINE_CHARS = 200;

/** What a hunk adds that can say why: its comment lines and test names. */
export interface CodeReason {
  hunk: Hunk;
  lines: string[];
}

/**
 * The comment lines and test names that each hunk adds, in diff order.
 * Mechanical hunks and lines that only steer a tool are left out.
 */
export function codeReasons(hunks: readonly Hunk[]): CodeReason[] {
  return hunks.flatMap((hunk) => {
    if (hunk.mechanical) return [];
    const lines: string[] = [];
    for (const line of hunk.lines) {
      if (lines.length === LINES_PER_HUNK) break;
      if (line.kind !== "add") continue;
      const content = line.content.trim();
      const test = TEST_NAME.exec(content);
      if (test) {
        lines.push(content.slice(0, LINE_CHARS));
        continue;
      }
      const comment = COMMENT_START.exec(content);
      if (!comment) continue;
      const words = (comment[2] ?? "").replace(/\*\/$|-->$|"""$|'''$/, "").trim();
      // A comment worth reading has a few words in it.
      if (words.length < 12 || !words.includes(" ") || TOOL_COMMENT.test(content)) continue;
      lines.push(content.slice(0, LINE_CHARS));
    }
    return lines.length > 0 ? [{ hunk, lines }] : [];
  });
}

/** Collapses whitespace, for matching a quote against its source. */
export function normaliseSpace(text: string): string {
  return text.replace(/\s+/g, " ").trim();
}

/** True when `quote` is in `text`, ignoring case and runs of whitespace. */
export function quoteIn(quote: string, text: string): boolean {
  const q = normaliseSpace(quote).toLowerCase();
  return q.length > 0 && normaliseSpace(text).toLowerCase().includes(q);
}
